        {
            type: 'work',
            title: 'Senior Full Stack Developer',
            company: 'Digital Solutions Inc.',
            period: '2023 - Present',
            desc: 'Leading development of enterprise-scale web applications, mentoring junior developers, and optimizing system architectures.',
        },
        {
            type: 'work',
            title: 'Full Stack Developer',
            company: 'Tech Innovators',
            period: '2021 - 2023',
            desc: 'Developed and maintained various client projects using MERN stack. Improved application performance by 40%.',
        },
        {
            type: 'education',
            title: 'Bachelor of Computer Science',
            company: 'University of Engineering and IT',
            period: '2023 - 2027',
            desc: 'Graduated with honors. Focused on algorithms, database management, and web technologies.',
        },
    ];

    return (
        <section className="section-padding bg-white dark:bg-dark-lighter">
            <div className="max-w-4xl mx-auto">
                <div className="text-center mb-16">
                    <h2 className="text-3xl md:text-4xl font-bold mb-4">
                        My <span className="gradient-text">Journey</span>
                    </h2>
                    <p className="text-slate-600 dark:text-slate-400 text-lg">
                        A timeline of my professional experience and educational background.
                    </p>
                </div>

                <div className="relative">
                    {/* Central Line */}
                    <div className="absolute left-4 md:left-1/2 h-full w-0.5 bg-slate-200 dark:bg-slate-800 -translate-x-1/2" />

                    <div className="space-y-12">
                        {experiences.map((exp, idx) => (
                            <motion.div
                                key={idx}
                                initial={{ opacity: 0, x: idx % 2 === 0 ? 50 : -50 }}
                                whileInView={{ opacity: 1, x: 0 }}
                                viewport={{ once: true }}
                                className={`relative flex items-center justify-between w-full ${idx % 2 === 0 ? 'md:flex-row-reverse' : ''
                                    }`}
                            >
                                {/* Connector Dot */}
                                <div className="absolute left-4 md:left-1/2 w-4 h-4 rounded-full bg-primary-light border-4 border-white dark:border-dark-lighter z-10 -translate-x-1/2" />

                                <div className="ml-12 md:ml-0 md:w-[45%]">
                                    <div className={`glass dark:glass-dark p-6 rounded-2xl hover:border-primary-light/50 transition-colors ${idx % 2 !== 0 ? 'md:text-right' : ''
                                        }`}>
                                        <div className={`flex items-center gap-3 mb-4 ${idx % 2 !== 0 ? 'md:flex-row-reverse' : ''
                                            }`}>
                                            <div className="w-10 h-10 rounded-full bg-primary-light/10 text-primary-light flex items-center justify-center shrink-0">
                                                {exp.type === 'work' ? (
                                                    <Briefcase className="w-5 h-5" />
                                                ) : (
                                                    <GraduationCap className="w-5 h-5" />
                                                )}
                                            </div>
                                            <span className="text-sm font-bold text-primary-light">{exp.period}</span>
                                        </div>
                                        <h3 className="text-xl font-bold dark:text-white mb-1">{exp.title}</h3>
                                        <div className="text-slate-500 dark:text-slate-400 font-medium mb-4">
                                            {exp.company}
                                        </div>
                                        <p className="text-slate-600 dark:text-gray-400 leading-relaxed text-sm md:text-base">
                                            {exp.desc}
                                        </p>
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Experience;

import React from 'react';
import { motion } from 'framer-motion';
import { ArrowRight, Download } from 'lucide-react';

const Hero = () => {
    return (
        <section className="relative w-full h-screen flex items-center justify-center overflow-hidden">
            {/* Background Gradient Animation */}
            <div className="absolute inset-0 z-0 bg-slate-50 dark:bg-dark">
                <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] rounded-full bg-primary-light/20 blur-[120px] animate-pulse" />
                <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] rounded-full bg-secondary-light/20 blur-[120px] animate-pulse" />
            </div>

            <div className="relative z-10 max-w-7xl mx-auto px-6 text-center">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.6 }}
                >
                    <span className="inline-block py-1 px-4 rounded-full bg-primary-light/10 text-primary-light text-sm font-medium mb-6">
                        Welcome to my portfolio
                    </span>
                    <h1 className="text-5xl md:text-7xl font-bold mb-6 tracking-tight">
                        Hi, I'm <span className="gradient-text">Muhammad Rizwan</span>
                    </h1>
                    <h2 className="text-2xl md:text-3xl font-medium text-slate-600 dark:text-slate-400 mb-8">
                        Full Stack Developer
                    </h2>
                    <p className="max-w-2xl mx-auto text-lg text-slate-600 dark:text-slate-400 mb-10 leading-relaxed">
                        Crafting high-performance, beautiful, and user-centric web applications with modern technologies.
                        Let's turn your ideas into digital reality.
                    </p>

                    <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
                        <motion.a
                            href="#projects"
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            className="btn-primary flex items-center gap-2"
                        >
                            View Projects <ArrowRight className="w-4 h-4" />
                        </motion.a>
                        <motion.a
                            href="#contact"
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            className="px-6 py-3 rounded-full border-2 border-slate-200 dark:border-slate-800 font-medium hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                        >
                            Contact Me
                        </motion.a>
                    </div>
                </motion.div>

                {/* Scroll Indicator */}
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 1, duration: 1 }}
                    className="absolute bottom-10 left-1/2 -translate-x-1/2"
                >
                    <div className="w-6 h-10 border-2 border-slate-300 dark:border-slate-700 rounded-full flex justify-center p-1">
                        <motion.div
                            animate={{ y: [0, 15, 0] }}
                            transition={{ repeat: Infinity, duration: 1.5 }}
                            className="w-1.5 h-1.5 bg-primary-light rounded-full"
                        />
                    </div>
                </motion.div>
            </div>
        </section>
    );
};

export default Hero;

import React, { useState, useEffect } from 'react';
import { useTheme } from '../context/ThemeContext';
import { Moon, Sun, Menu, X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const Navbar = () => {
    const { isDark, toggleTheme } = useTheme();
    const [isScrolled, setIsScrolled] = useState(false);
    const [isMenuOpen, setIsMenuOpen] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            setIsScrolled(window.scrollY > 20);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const navLinks = [
        { name: 'Home', href: '#' },
        { name: 'About', href: '#about' },
        { name: 'Skills', href: '#skills' },
        { name: 'Projects', href: '#projects' },
        { name: 'Contact', href: '#contact' },
    ];

    return (
        <nav
            className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${isScrolled
                    ? 'py-3 bg-white/70 dark:bg-dark/70 backdrop-blur-md shadow-lg border-b border-white/10'
                    : 'py-6 bg-transparent'
                }`}
        >
            <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
                <motion.div
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="text-2xl font-bold gradient-text"
                >
                    Rizwan
                </motion.div>

                {/* Desktop Links */}
                <div className="hidden md:flex items-center space-x-8">
                    {navLinks.map((link) => (
                        <a
                            key={link.name}
                            href={link.href}
                            className="text-sm font-medium hover:text-primary-light transition-colors dark:text-gray-300"
                        >
                            {link.name}
                        </a>
                    ))}
                    <button
                        onClick={toggleTheme}
                        className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                    >
                        {isDark ? <Sun className="w-5 h-5 text-yellow-400" /> : <Moon className="w-5 h-5 text-slate-700" />}
                    </button>
                </div>

                {/* Mobile Toggle */}
                <div className="md:hidden flex items-center space-x-4">
                    <button onClick={toggleTheme} className="p-2">
                        {isDark ? <Sun className="w-5 h-5 text-yellow-400" /> : <Moon className="w-5 h-5 text-slate-700" />}
                    </button>
                    <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="p-2">
                        {isMenuOpen ? <X className="w-6 h-6 dark:text-white" /> : <Menu className="w-6 h-6 dark:text-white" />}
                    </button>
                </div>
            </div>

            {/* Mobile Menu */}
            <AnimatePresence>
                {isMenuOpen && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="md:hidden bg-white dark:bg-dark border-b border-gray-200 dark:border-gray-800"
                    >
                        <div className="px-6 py-8 flex flex-col space-y-4">
                            {navLinks.map((link) => (
                                <a
                                    key={link.name}
                                    href={link.href}
                                    onClick={() => setIsMenuOpen(false)}
                                    className="text-lg font-medium dark:text-gray-300"
                                >
                                    {link.name}
                                </a>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </nav>
    );
};

export default Navbar;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Github, ExternalLink, X } from 'lucide-react';

const Projects = () => {
    const [selectedProject, setSelectedProject] = useState(null);

